import{z as B,x as d,o as r,c as A,q as t,j as i,D as e,d as n,s,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"2010 闪电崩盘","description":"","frontmatter":{"title":"2010 闪电崩盘","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/flash-crash-2010.md","filePath":"quant/flash-crash-2010.md","lastUpdated":1791063341000}'),p={name:"quant/flash-crash-2010.md"};function h(m,a,u,F,T,D){const l=d("Mermaid");return r(),A("div",null,[a[2]||(a[2]=t('<h1 id="_2010-闪电崩盘" tabindex="-1">2010 闪电崩盘 <a class="header-anchor" href="#_2010-闪电崩盘" aria-label="Permalink to &quot;2010 闪电崩盘&quot;">​</a></h1><div class="epigraph"><p>2010 年 5 月 6 日，美国指数在数分钟内崩落又回抽。事后来看，那不是一个「有人知道价值腰斩」的信息事件，而是流动性供给在压力下撤退、市价卖单打进空簿的路径。</p><footer>—— Kirilenko, Kyle, Samadi and Tuzun, The Flash Crash: High-Frequency Trading in an Electronic Market, Journal of Finance, 2017；机制背景见 CFTC–SEC, Findings Regarding the Market Events of May 6, 2010</footer></div><p><a href="/quant/brogaard-hft-discovery">Brogaard</a>写平静期与一般样本里 HFT 的发现与做市。缺口是压力路径：当临时流动性需求极大、供给撤退时，连续 LOB 的 \\(P(Q)\\) 可以走到与永久价值无关的价格。Kirilenko、Kyle、Samadi 与 Tuzun（2017）用账户层期货数据刻画闪电崩盘中的高频与中介行为；Easley、López de Prado 与 O&#39;Hara 从订单流毒性角度讨论同一事件。本课写机制，不复述逐分钟新闻。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Grossman–Miller 的暂时折让在 \\(M\\) 突然变小时可以极大。电子簿上 \\(M\\) 变小的实现是：做市账户达到库存或亏损限额、算法关闭、挂单撤空。此时若仍有大的市价卖（包括对冲与止损），价格沿空簿下行，触发更多算法卖，反馈完成。问题是把这条路径与「新的宏观信息」区分开：若主要是暂时成分，应有快速回复；若 HFT 是主因，应看到他们净卖在跌势中放大。Kirilenko 等人的结论更接近：高频交易者在事件中仍高频买卖，但没有吸收全部压力，传统中介与互惠型卖压才是流量主体——细节以原文账户分类为准，本课要的是<strong>供给弹性在压力下不是常数</strong>。</p><p>Easley–O&#39;Hara 事件不确定的反面：这是无（匹配的）信息事件却有极端价格路径，PIN 式「有事件」会被量与不平衡误触发。</p><p><span class="marginnote">数字实例：平时买一档挂 200 手，卖 1000 手市价只吃穿几档、冲击几十个基点；空簿时同档只挂 5 手，同样的 1000 手要向下扫几百档——卖压相同，「价格×数量」的路径完全不同，这就是 \\(M\\) 变小的直观含义。</span></p><h3 id="空簿上的市价单" tabindex="-1">空簿上的市价单 <a class="header-anchor" href="#空簿上的市价单" aria-label="Permalink to &quot;空簿上的市价单&quot;">​</a></h3><p><a href="/quant/lob-structure">LOB 结构</a>里深度是冲击路径。空簿时路径没有定义上的边界，直到碰到远期挂单、熔断或有人愿意接。Glosten 曲线假定竞争性限价供给还在；闪电崩盘是供给函数暂时消失。均场密度 \\(\\rho\\) 在几分钟内可以接近零，PDE 稳态无用。</p><p><span class="marginnote">不要把闪电崩盘写成「HFT 发明了崩盘」。更准确的句子是：连续电子簿加市价指令、加相互挂钩的指数产品，在供给撤退时允许价格走得比人工楼层时代更快。HFT 既是供给也是可能的加速器。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>事件研究用账户分类：高频做市、中介、基本面卖盘。看净持仓路径、是否在最低点附近买入（吸收）还是继续卖。监管报告重建 Waddell 等大单在 E-mini 上的执行与跨市场传导（期货领先股票、ETF）。机制检验：回复速度、跨品种同步、是否触发熔断逻辑。事后政策是 LULD 与期货熔断校准，那是设计课的对象。</p><p>毒性：VPIN 一类度量在事件前升高的叙述，争议在于事后拟合。本课只保留：订单流不平衡在供给薄时对价格的映射变陡，与 Kyle \\(\\lambda\\) 时变同方向，不是新的价值发现。</p>',13)),(r(),i(o,null,{default:e(()=>[s(l,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20Sell%5B%22%E5%A4%A7%E7%9A%84%E6%B5%81%E5%8A%A8%E6%80%A7%E5%8D%96%E5%8E%8B%22%5D%20--%3E%20Thin%5B%22%E5%81%9A%E5%B8%82%E5%BA%93%E5%AD%98%2F%E9%A3%8E%E6%8E%A7%E8%BE%BE%E9%99%90%22%5D%0A%20%20Thin%20--%3E%20Empty%5B%22%E5%8F%AF%E8%A7%81%E7%B0%BF%E5%8F%98%E7%A9%BA%22%5D%0A%20%20Empty%20--%3E%20Px%5B%22%E5%B8%82%E4%BB%B7%E6%B2%BF%E7%A9%BA%E7%B0%BF%E4%B8%8B%E8%A1%8C%22%5D%0A%20%20Px%20--%3E%20More%5B%22%E6%AD%A2%E6%8D%9F%E4%B8%8E%E5%AF%B9%E5%86%B2%E5%86%8D%E5%8D%96%22%5D%0A%20%20More%20--%3E%20Thin%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[n("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"反馈有三层。库存：Ho–Stoll 偏度把报价下移，若限额是硬约束则直接撤单。信息推断：看到暴跌的人提高「有事件」后验，限价更不敢挂，被捡预期升。机械：止损、杠杆强平、跨市场套利在错误价格上反向（套利者若也被风控关掉，纠错消失）。Budish 式狙击在崩盘中不是主叙事：问题不是一跳公共新闻，而是持续的单向流遇到无弹性供给。",-1)),a[5]||(a[5]=E("p",null,"回复证明永久成分有限，符合 Grossman–Miller 而不是新的 \\(V\\)。但回复过程中仍有人在错误价格成交，分配效应真实。效率度量若用全日 VR，会把这几分钟平均掉。",-1)),(r(),i(o,null,{default:e(()=>[s(l,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20DROP%5B%22%E4%BB%B7%E6%A0%BC%E5%BF%AB%E9%80%9F%E4%B8%8B%E8%A1%8C%22%5D%20--%3E%20L1%5B%22%E5%BA%93%E5%AD%98%E5%B1%82%EF%BC%9A%E6%8A%A5%E4%BB%B7%E4%B8%8B%E7%A7%BB%E6%88%96%E6%92%A4%E5%8D%95%22%5D%0A%20%20DROP%20--%3E%20L2%5B%22%E4%BF%A1%E6%81%AF%E5%B1%82%EF%BC%9A%E8%A7%82%E5%AF%9F%E8%80%85%E6%8A%AC%E9%AB%98%E3%80%8C%E6%9C%89%E4%BA%8B%E4%BB%B6%E3%80%8D%E5%90%8E%E9%AA%8C%22%5D%0A%20%20DROP%20--%3E%20L3%5B%22%E6%9C%BA%E6%A2%B0%E5%B1%82%EF%BC%9A%E6%AD%A2%E6%8D%9F%20%2F%20%E5%BC%BA%E5%B9%B3%20%2F%20%E5%A5%97%E5%88%A9%E8%85%BF%E5%90%8C%E5%90%91%22%5D%0A%20%20L1%20--%3E%20THIN%5B%22%E4%BE%9B%E7%BB%99%E6%9B%B4%E8%96%84%E3%80%81%E4%B9%B0%E7%9B%98%E6%9B%B4%E6%80%AF%22%5D%0A%20%20L2%20--%3E%20THIN%0A%20%20L3%20--%3E%20THIN%0A%20%20THIN%20--%3E%20DEEPER%5B%22%E5%90%8C%E9%87%8F%E5%8D%96%E5%8E%8B%E6%89%93%E5%BE%97%E6%9B%B4%E6%B7%B1%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p><span class="marginnote">直觉类比：限价挂单像商场里的消防岗——平静时人人愿意站岗赚价差；警报一响（亏损限额触发），站岗者同时撤走，逃难的人（市价卖单）在空走廊里互相踩踏。价格下探的深度，就是那条走廊被挤空的深度。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>2010 年美股/指数期货结构不能外推到涨跌停市场：后者用价格栅格截断路径，换成开板与排队问题。加密与外汇有过类似闪崩，供给撤退逻辑同构，清算与做市义务不同。把每一次大幅回撤叫做闪电崩盘，会失去「无信息、空簿、快速回复」这三个要件。</p><p><span class="marginnote">常见误区：把任何单日大跌都叫「闪电崩盘」。判定要件有三——没有匹配幅度的新信息、簿上供给撤退、价格在分钟级快速回抽。2010 年 5 月 6 日道指盘中暴跌近千点又迅速收回大半，符合；寻常的恐慌抛售不符合。</span></p><p><span class="marginnote">执行上的教训不是「永远不要用市价」，而是大单在供给可能撤退的状态下不能假设 \\(P(Q)\\) 仍由平时宏观形状给出。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>闪电崩盘是流动性供给撤退后市价单打空簿的路径，永久信息不必匹配价格幅度。</li><li>高频账户是结构的一部分，原文分类并不支持「HFT 单方面造成崩盘」的简单句。</li><li>\\(\\lambda\\) 与深度在压力下内生崩溃，平静期做市画像不能外推。</li><li>出处：Kirilenko, Kyle, Samadi and Tuzun, <em>Journal of Finance</em>, 2017；CFTC–SEC, <em>Findings Regarding the Market Events of May 6, 2010</em>；毒性讨论见 Easley, López de Prado and O&#39;Hara 对闪崩微观结构的论述。</li></ul>',7))])}const C=B(p,[["render",h]]);export{c as __pageData,C as default};
